INSERT INTO "triviaItems" (id, category, question, "correctAnswer", "wrongAnswer1", "wrongAnswer2", hint, difficulty, explanation) VALUES
('net-001', 'NETWORKING', 'Which two Catalyst switch models include dedicated data processing units?', '9400X and 9500X', '9300 and 9200', '9000 and Over 9000', 'Think X marks the spot for extreme performance.', 'MEDIUM', 'The Catalyst 9400X and 9500X include dedicated DPUs (Data Processing Units) that enable advanced security and analytics at the switching layer without impacting forwarding performance.'),
('net-002', 'NETWORKING', 'Which Nexus switch series includes models with DPUs for AI workloads?', 'Nexus 9300', 'Nexus 7000', 'Nexus 42', 'It''s in the 9000 family, but lower than 9500.', 'MEDIUM', 'The Nexus 9300 series includes models with dedicated DPUs designed to accelerate AI workloads, provide inline security, and handle telemetry processing without affecting network throughput.'),
('net-003', 'NETWORKING', 'What network speed optics did Cisco announce for AI-ready data centers?', '800G', '400G', '88 MPH', 'Double what you think is already really fast.', 'MEDIUM', 'Cisco announced 800 Gigabit Ethernet optics for AI-ready data centers, supporting the massive bandwidth requirements of GPU-to-GPU communication in AI training clusters.'),
('net-004', 'NETWORKING', 'What is Cisco''s new switch series designed for AI data centers with NVIDIA GPU integration?', 'Nexus HyperFabric', 'Catalyst AI', 'Cisco SkyNet', 'It''s Hyper-focused on fabric connectivity.', 'MEDIUM', 'Nexus HyperFabric is Cisco''s purpose-built switching platform for AI data centers, featuring deep integration with NVIDIA GPUs and optimized for ultra-low latency AI workloads.'),
('net-005', 'NETWORKING', 'Which fabrics does the Unified Nexus Dashboard consolidate?', 'ACI, VXLAN, and traditional networks', 'Campus, WAN, and Data Center', 'Cotton, Silk, and Polyester', 'Think about the underlying network protocols, not locations.', 'MEDIUM', 'The Unified Nexus Dashboard consolidates management of ACI (Application Centric Infrastructure), VXLAN-based networks, and traditional switching fabrics into a single interface.'),
('net-006', 'NETWORKING', 'What security capability do Smart Switches deliver at line rate?', 'DPU-based firewalling', 'AI threat detection', 'Enterprise Trust Issues', 'It uses those special processing units we keep mentioning.', 'MEDIUM', 'Smart Switches use embedded DPUs to deliver line-rate firewall inspection on every port without performance degradation, extending zero-trust security to the switching layer.'),
('net-007', 'NETWORKING', 'Which Cisco technology provides AI-driven security enforcement across distributed networks?', 'Hypershield', 'Hyperfabric', 'Hypercolour', 'It''s hyper-focused on distributed security.', 'MEDIUM', 'Cisco Hypershield provides AI-driven security enforcement across distributed networks using dual data planes and compensating controls to protect against threats at massive scale.'),
('net-008', 'NETWORKING', 'What Cisco platform combines routing, SD-WAN, and firewall in a single appliance?', 'Cisco 8000 Secure Router', 'ISR 4000 Series', 'Swiss Army Router', 'It''s in the 8000 family and it''s Secure.', 'MEDIUM', 'The Cisco 8000 Secure Router series combines high-performance routing, SD-WAN capabilities, and next-generation firewall functions in a single platform for simplified branch deployments.'),
('net-009', 'NETWORKING', 'What is Cisco''s AI-based collaborative workspace for advanced troubleshooting?', 'AI Canvas', 'Webex AI Assistant', 'Clippy 2.0', 'It helps you see with a thousand perspectives.', 'MEDIUM', 'ThousandEyes Copilot is an AI-powered collaborative workspace that helps network teams diagnose complex issues faster by providing intelligent insights and automated troubleshooting recommendations.'),
('net-010', 'NETWORKING', 'What does Cisco call its unified security strategy including Secure Firewall and Hypershield?', 'Hybrid Mesh Firewall', 'Unified Security Platform', 'Security Spaghetti Junction', 'It''s a mesh that works in hybrid environments.', 'MEDIUM', 'Hybrid Mesh Firewall is Cisco''s strategy to unify security enforcement across Cisco Secure Firewall, Hypershield, Meraki, ASA, and third-party firewalls under a single policy framework.'),
('net-011', 'NETWORKING', 'Which technology partnership enabled Cisco to add DPUs to switches?', 'NVIDIA', 'Intel', 'AMD', 'The same company famous for GPUs also makes DPUs.', 'EASY', 'Cisco partnered with NVIDIA to integrate NVIDIA BlueField DPUs into switches, enabling advanced processing capabilities for security, telemetry, and AI workload acceleration.'),
('net-012', 'NETWORKING', 'What type of security does Cisco''s Secure Router series include against quantum threats?', 'Post-quantum cryptography', 'Quantum-resistant encryption', 'Schrödinger Pro', 'It comes after quantum computing becomes a threat.', 'MEDIUM', 'Cisco''s Secure Router series includes post-quantum cryptography algorithms designed to protect against future attacks from quantum computers that could break current encryption standards.'),
('net-013', 'NETWORKING', 'What does Cisco call its vision of using AI agents to diagnose network issues proactively?', 'Agentic AI', 'Synthetic Support Desk', 'Network Psychics United', 'The agents are doing the work for you.', 'MEDIUM', 'Agentic AI is Cisco''s vision where AI agents autonomously diagnose, predict, and resolve network issues before they impact users, transforming network operations.'),
('net-014', 'NETWORKING', 'What is the maximum switching capacity of the Catalyst 9000X series?', '25.6 Tbps', '25.6 Gbps', '25.6 Mbps', 'Think big. Seriously, big.', 'MEDIUM', 'The Catalyst 9000X series delivers up to 25.6 Terabits per second of switching capacity, supporting high-density, high-performance enterprise and data center deployments.'),
('net-015', 'NETWORKING', 'Which Catalyst switch platform supports Universal PoE for high-power devices?', 'Catalyst 9000 Series', 'Catalyst 3850 Series', 'Catalyst Unlimited Power Edition', 'It''s the current flagship 9000 family.', 'EASY', 'The Catalyst 9000 Series supports Universal PoE (UPoE) delivering up to 60W per port, enabling high-power devices like PTZ cameras, wireless access points, and digital displays.'),
('net-016', 'NETWORKING', 'What power budget can Cisco''s Ultra PoE switches deliver per port?', '90W', '60W', '1.21 Gigawatts', 'It''s 50% more than Universal PoE.', 'MEDIUM', 'Cisco''s Ultra PoE (UPoE+) switches can deliver up to 90 watts per port, supporting the most power-hungry devices like LED lighting, building automation, and advanced PTZ cameras.'),
('net-017', 'NETWORKING', 'Which Cisco switch operating system powers both Catalyst and Nexus platforms?', 'IOS-XE', 'NX-OS', 'S-OS', 'It''s the eXtended Edition of a classic.', 'MEDIUM', 'Cisco IOS XE is the modern operating system powering Catalyst switches, while select Nexus platforms also support it, providing consistency across enterprise and data center environments.'),
('net-018', 'NETWORKING', 'What is the name of Cisco''s intent-based networking platform for enterprise networks?', 'Cisco Catalyst Center', 'Cisco Prime Infrastructure', 'Cisco SkyNet', 'It understands the DNA of your network.', 'MEDIUM', 'Cisco DNA Center is the intent-based networking platform that automates network provisioning, policy enforcement, and assurance across the enterprise using AI and machine learning.'),
('net-019', 'NETWORKING', 'Which Catalyst switch series is optimized for cloud-scale deployments?', 'Cisco Catalyst 9000 Series', 'Cisco Nexus 9000 Series', 'Cisco Nimbus 9000 Series', 'The highest number in the current lineup.', 'MEDIUM', 'The Catalyst 9000 Series is purpose-built for cloud-scale deployments with programmable ASICs, telemetry, automation APIs, and the performance needed for modern hybrid cloud architectures.'),
('net-020', 'NETWORKING', 'What switching technology enables lossless Ethernet for storage and AI workloads?', 'Priority Flow Control', 'Quality of Service', 'No Packet Left Behind Protocol', 'It controls the flow with priority.', 'MEDIUM', 'Priority Flow Control (PFC) enables lossless Ethernet by pausing transmission on congested queues, essential for storage protocols like iSCSI and AI workloads that cannot tolerate packet loss.'),
('net-021', 'NETWORKING', 'Which Nexus platform is designed specifically for spine-leaf architectures?', 'Nexus 9000 Series', 'Nexus 7000 Series', 'Nexus 5000 Series', 'It''s the 9000 series built for modern fabrics.', 'MEDIUM', 'The Nexus 9000 series is purpose-built for spine-leaf data center architectures, offering ultra-low latency, high bandwidth, and support for both ACI and NX-OS modes.'),
('net-022', 'NETWORKING', 'What is the total throughput capacity of the Nexus 9000 series flagship model?', '64 Tbps', '32 Tbps', '16 Tbps', 'Double what seems already unreasonably fast.', 'HARD', 'The Nexus 9000 series flagship models deliver up to 64 Terabits per second of throughput, supporting the most demanding hyperscale data center and AI infrastructure requirements.'),
('net-023', 'NETWORKING', 'Which Cisco switching feature provides microsecond-level network telemetry?', 'Streaming Telemetry', 'NetFlow', 'Gossip Protocol', 'It streams data in real time, not in batches.', 'MEDIUM', 'Streaming Telemetry provides microsecond-level visibility into network behavior by continuously pushing real-time data, unlike traditional polling methods, enabling faster anomaly detection.'),
('net-024', 'NETWORKING', 'What technology allows Cisco switches to segment networks without VLANs?', 'TrustSec', 'VRF', 'VLAN-Free Zones', 'It''s about trust and security, not VLANs.', 'MEDIUM', 'Cisco TrustSec uses Security Group Tags (SGTs) to segment networks based on identity rather than IP addresses or VLANs, simplifying policy enforcement and improving security.'),
('net-025', 'NETWORKING', 'Which Catalyst series includes Wi-Fi 7 integrated access points?', 'Catalyst 9130', 'Catalyst 9800', 'Catalyst 404', 'It''s the access point series, not the wireless controller.', 'MEDIUM', 'The Catalyst 9130 series access points support Wi-Fi 7 (802.11be), delivering multi-gigabit speeds, ultra-low latency, and support for dense, high-performance wireless environments.');
INSERT INTO "triviaItems" (id, category, question, "correctAnswer", "wrongAnswer1", "wrongAnswer2", hint, difficulty, explanation) VALUES
('sec-001', 'SECURITY', 'This framework includes distributed firewalls and Hypershield:', 'Hybrid Mesh Firewall', 'Hybrid Cloud Defense Matrix', 'Firewall Farm Federation', 'This portfolio adds enforcement points across diverse environments.', 'MEDIUM', 'Cisco''s Hybrid Mesh Firewall is a distributed security fabric that includes Cisco and third-party firewalls, Cisco Hypershield, and Cisco Secure Workload for zero-trust segmentation.'),
('sec-002', 'SECURITY', 'What does ZTNA stand for?', 'Zero Trust Network Access', 'Zero Threat Network Architecture', 'Zombies That Never Attack', 'Ensures identity-driven access for users, devices, and AI agents.', 'EASY', 'Universal ZTNA stands for Universal Zero Trust Network Access, ensuring seamless, identity-driven access while simplifying secure connectivity across hybrid environments.'),
('sec-003', 'SECURITY', 'What is the per-RU performance density of the Cisco Secure Firewall 6100?', '200 Gbps', '20 Gbps', '2 Gbps', 'The biggest number is usually correct!', 'MEDIUM', 'The Cisco Secure Firewall 6100 Series delivers 200 Gbps per rack unit, providing the highest performance density for data center firewalling.'),
('sec-004', 'SECURITY', 'Which branch firewall series has integrated SD-WAN?', '200 Series', '8000 Series', '404 Series', 'Delivers up to 3x price-performance compared to competition.', 'MEDIUM', 'The Cisco Secure Firewall 200 Series is designed for distributed branches with integrated SD-WAN at up to 3x price-performance compared to competition.'),
('sec-005', 'SECURITY', 'Name the Cisco Security Cloud Control unified policy engine:', 'Mesh Policy Engine', 'Identity Service Engine', 'Internal Combustion Engine', 'Everything connects to everything.', 'MEDIUM', 'The Mesh Policy Engine enables teams to define a single intent-based policy enforced across Cisco and third-party firewalls, simplifying operations.'),
('sec-006', 'SECURITY', 'This Cisco platform offers passwordless authentication for phishing resistance:', 'Duo IAM', 'Cisco Identity Services Engine', 'Cisco SecureX', 'Includes proximity verification without clunky hardware tokens.', 'MEDIUM', 'Duo IAM acts as an identity broker with passwordless options and unique proximity verification, layering phishing resistance on existing identity infrastructure.'),
('sec-007', 'SECURITY', 'Which protocol does Cisco support for agent-to-enterprise connections?', 'Model Context Protocol', 'Agent to Agent', 'Master Control Program', 'Named after Model Context, not Master Control from Tron.', 'MEDIUM', 'Cisco supports Model Context Protocol (MCP), enabling agentic AI to securely access enterprise resources with automated discovery and delegated authorization.'),
('sec-008', 'SECURITY', 'Which products secure agentic identities together?', 'Duo IAM, Secure Access, and AI Defense', 'Duo IAM, Secure Access, and Splunk', 'Duo IAM, Secure Access, and Webex', 'Unified under Security Cloud Control for agentic AI security.', 'MEDIUM', 'Cisco Duo IAM, Identity Intelligence, Secure Access, and AI Defense work together under Security Cloud Control to secure agentic identities.'),
('sec-009', 'SECURITY', 'What edge security service integrates with all SD-WAN offerings, including Meraki?', 'SASE', 'SASI', 'SASSY', 'The definition keeps shifting, but edge security is critical.', 'MEDIUM', 'SASE is simplified through integration of all Cisco SD-WAN offerings with Cisco Secure Access, enabling optimal branch connectivity with unified SSE policy.'),
('sec-010', 'SECURITY', 'Which router series supports NGFW via Security Cloud Control?', '8000 Series', '3800 Series', '800 Series', 'Part of Cisco Catalyst SD-WAN with expanded enforcement.', 'MEDIUM', 'The Cisco 8000 Secure Router Series supports next-generation firewall capabilities on Catalyst SD-WAN through unified policy management.'),
('sec-011', 'SECURITY', 'Name the acquisition that became the foundation of Cisco Data Fabric:', 'Splunk', 'Thousand Eyes', 'Snort', 'If you can imagine it, you can build it in SPL.', 'MEDIUM', 'The Cisco Security Cloud App for Splunk delivers deeper support for Cisco Secure Firewall Threat Defense, enabling enriched correlation and detection.'),
('sec-012', 'SECURITY', 'Cisco Splunk accelerates which security workflow?', 'Traffic Diagnosis, Inspection, and Response', 'Traffic Diagnosis, Inspection, and Recovery', 'Total Destruction after Incident Replay', 'Enhanced through deeper Cisco Secure Firewall integration.', 'MEDIUM', 'TDIR stands for Threat Detection, Investigation and Response - comprehensive security workflows enhanced through Cisco and Splunk integrations.'),
('sec-013', 'SECURITY', 'Which Cisco switches are "Hypershield-ready"?', 'Smart Switches', 'Catalyst Switches', 'Dumb Switches', 'Integrate with Security Cloud Control for unified policy.', 'MEDIUM', 'C9000 Smart Switches are Hypershield-ready, serving as enforcement points for unified policy management through Security Cloud Control.'),
('sec-014', 'SECURITY', 'Which data center fabric integrates with Cisco Security Cloud Control?', 'ACI', 'VXLAN Fabric', 'SD-Access Fabric', 'Enables unified policy management across data centers.', 'MEDIUM', 'Cisco ACI data center fabrics integrate with Security Cloud Control for expanded enforcement points as part of the Hybrid Mesh Firewall strategy.'),
('sec-015', 'SECURITY', 'Which switches support post-quantum cryptography?', 'Smart Switches', 'Catalyst Switches', 'Schrödinger Switches', 'Protection against future quantum decryption attacks.', 'MEDIUM', 'Cisco Smart Switches include post-quantum cryptography to protect against the threat of quantum computers breaking current encryption standards.'),
('sec-016', 'SECURITY', 'Which switches embed DPUs in each switchport for line-rate firewalling?', 'Smart Switches', 'Meraki Switches', 'Paranoid Switches', 'Line-rate firewalling in every single port.', 'MEDIUM', 'Cisco Smart Switches embed Data Processing Units (DPUs) in each switchport, enabling line-rate firewall inspection on every port without performance degradation.'),
('sec-017', 'SECURITY', 'Name Cisco''s platform with dual data planes for low-risk upgrades:', 'Hypershield', 'Hyperfabric', 'Hyperactive', 'Revolutionary security platform with dual data planes.', 'MEDIUM', 'Cisco Hypershield uses dual data planes to enable zero-downtime upgrades, allowing security policy updates without service interruption or risk.'),
('sec-018', 'SECURITY', 'Name Cisco''s platform with compensating controls for the patch gap:', 'Hypershield', 'Hyperconverged', 'Hypercolour', 'Addresses the gap between risk discovery and patch deployment.', 'MEDIUM', 'Cisco Hypershield provides compensating controls that protect vulnerabilities immediately upon discovery, before patches can be applied and tested.');
INSERT INTO "triviaItems" (id, category, question, "correctAnswer", "wrongAnswer1", "wrongAnswer2", hint, difficulty, explanation) VALUES
('col-001', 'COLLABORATION', 'How many specialized AI Agents were introduced for Webex Suite at WebexOne 2025?', '5', '7', '42', 'You can count them on one hand.', 'MEDIUM', 'Cisco introduced 10 specialized AI Agents for Webex Suite at WebexOne 2025, covering various collaboration scenarios from meeting assistance to workflow automation.'),
('col-002', 'COLLABORATION', 'What is Cisco''s cloud-connected operating system for collaboration devices?', 'RoomOS', 'WebexOS', 'SOS', 'Think about where these devices typically live.', 'EASY', 'RoomOS is Cisco''s cloud-connected operating system that powers Webex devices, providing intelligent features, security updates, and AI-powered capabilities.'),
('col-003', 'COLLABORATION', 'Which Apple device now supports sharing and manipulating 3D models in Webex meetings?', 'Vision Pro', 'iPad Pro', 'iPod', 'It''s Apple''s newest spatial computing device.', 'MEDIUM', 'Apple Vision Pro now supports sharing and manipulating 3D models in Webex meetings, enabling immersive spatial collaboration experiences.'),
('col-004', 'COLLABORATION', 'What AI-powered tool in Control Hub delivers analytics insights to IT teams?', 'Webex AI Assistant', 'Analytics Engine', 'Crystal Ball Pro', 'It''s an AI helper specifically for Webex.', 'MEDIUM', 'Webex AI Assistant in Control Hub provides IT teams with intelligent analytics insights, helping them proactively manage collaboration environments and optimize user experiences.'),
('col-005', 'COLLABORATION', 'What feature allows Webex meetings to continue even during internet disruptions or outages?', 'Webex Go', 'Meeting Continuity', 'Carrier Pigeon Mode', 'The name suggests mobility and keeping things moving.', 'MEDIUM', 'Webex Go allows meetings to continue seamlessly even during internet disruptions by automatically switching to cellular or alternative connections, ensuring uninterrupted collaboration.'),
('col-006', 'COLLABORATION', 'Which Webex Contact Center AI feature detects agent burnout in real time?', 'Agent Wellbeing', 'Performance Monitor', 'Stress-o-Meter', 'It focuses on the health and wellness of agents.', 'MEDIUM', 'Agent Wellbeing uses AI to detect signs of agent burnout in real time by analyzing interaction patterns, sentiment, and workload, helping supervisors intervene proactively.'),
('col-007', 'COLLABORATION', 'What does MCP stand for in the context of Webex AI Agent capabilities?', 'Model Context Protocol', 'Multi-Channel Processing', 'Master Control Program', 'It''s about providing context to AI models.', 'MEDIUM', 'Model Context Protocol (MCP) enables Webex AI Agents to securely access enterprise data and systems with proper context, allowing them to perform tasks on behalf of users.'),
('col-008', 'COLLABORATION', 'What new Cisco Desk Phone series was announced at WebexOne 2025?', '9900 Series', '8900 Series', '911 Series', 'It''s in the high 9000s range.', 'MEDIUM', 'The Cisco Desk Phone 9900 Series was announced at WebexOne 2025, featuring advanced AI capabilities, superior audio quality, and seamless Webex integration.'),
('col-009', 'COLLABORATION', 'Which messaging platforms are supported as digital channels in Contact Center Enterprise?', 'WhatsApp, Facebook Messenger, SMS', 'Telegram, WeChat, iMessage', 'Tinder, Bumble, eHarmony, Hinge', 'Think of the most popular global messaging platforms.', 'MEDIUM', 'Webex Contact Center Enterprise supports WhatsApp, Facebook Messenger, and SMS as digital channels, enabling customers to engage through their preferred messaging platforms.'),
('col-010', 'COLLABORATION', 'What Webex AI feature auto-generates action items from meeting summaries?', 'AI Actions', 'Smart Tasks', 'Nag Bot', 'The name directly describes what it does with AI.', 'MEDIUM', 'AI Actions automatically generates action items from meeting summaries and offers options to complete tasks directly within Webex, improving productivity and follow-through.'),
('col-011', 'COLLABORATION', 'What quality management solution auto-scores interactions and provides coaching?', 'Webex Workforce Optimization', 'Performance Improvement Protocol', 'The Judge', 'It optimizes your entire workforce, not just quality.', 'MEDIUM', 'Webex Workforce Optimization automatically scores customer interactions using AI, provides coaching recommendations, and helps supervisors improve agent performance across all channels.'),
('col-012', 'COLLABORATION', 'What intelligent feature on RoomOS automatically predicts meeting flow and adapts the camera mode?', 'Intelligent Director', 'Smart Framing', 'Psychic Mode', 'It directs the meeting like a film director.', 'MEDIUM', 'Intelligent Director uses AI to predict meeting flow and automatically adapts camera modes, ensuring the right people are framed at the right time for more natural collaboration.'),
('col-013', 'COLLABORATION', 'What analytics feature transcribes and summarizes calls to identify interaction patterns?', 'Conversation Intelligence', 'Call Analytics', 'Eavesdropper Pro', 'It makes conversations intelligent through analysis.', 'MEDIUM', 'Conversation Intelligence transcribes and summarizes customer calls, identifying common interaction drivers, sentiment trends, and coaching opportunities to improve contact center performance.'),
('col-014', 'COLLABORATION', 'What Webex Meetings feature uses AI to remove background noise in real time?', 'Noise Removal', 'Audio Enhancement', 'Dog Shoosher', 'It literally removes the noise.', 'EASY', 'Noise Removal uses AI to intelligently filter out background sounds like keyboard typing, barking dogs, and construction noise in real time, ensuring crystal-clear audio in meetings.'),
('col-015', 'COLLABORATION', 'Which Cisco device family includes the Desk, Board, and Room series?', 'Cisco Collaboration Devices', 'Webex Endpoints', 'Meeting Magic Series', 'They all work together for collaboration.', 'EASY', 'Cisco Collaboration Devices is the portfolio that includes Webex Desk devices, Board devices, and Room systems, all powered by RoomOS for intelligent collaboration experiences.'),
('col-016', 'COLLABORATION', 'What feature allows participants to join Webex meetings directly from Microsoft Teams?', 'Webex for Microsoft Teams', 'Cross-Platform Join', 'Endless Meetings Pro', 'It''s Webex embedded in Microsoft Teams.', 'MEDIUM', 'Webex for Microsoft Teams allows users to join Webex meetings directly from within Microsoft Teams without switching applications, enabling seamless cross-platform collaboration.'),
('col-017', 'COLLABORATION', 'What is the maximum number of participants supported in a Webex Webinar?', '100,000', '10,000', '1,000', 'It''s a six-figure number.', 'HARD', 'Webex Webinars support up to 100,000 participants, making it ideal for large-scale virtual events, town halls, and broadcasts with interactive Q&A and engagement features.'),
('col-018', 'COLLABORATION', 'Which Webex feature provides real-time translation and closed captioning during meetings?', 'Real-Time Translation', 'Live Captions', 'Babel Fish Mode', 'The feature name tells you exactly what it does.', 'MEDIUM', 'Real-Time Translation provides live translation and closed captioning in over 100 languages during Webex meetings, breaking down language barriers and improving accessibility for global teams.');
INSERT INTO "triviaItems" (id, category, question, "correctAnswer", "wrongAnswer1", "wrongAnswer2", hint, difficulty, explanation) VALUES
('dc-001', 'DATA_CENTER', 'What does ACI stand for in Cisco data center networking?', 'Application Centric Infrastructure', 'Automated Cloud Infrastructure', 'All Cables Included', 'It puts applications at the center of everything.', 'EASY', 'ACI stands for Application Centric Infrastructure, Cisco''s software-defined networking solution that automates data center fabric deployment and management based on application requirements.'),
('dc-002', 'DATA_CENTER', 'What does UCS stand for in Cisco''s compute platform?', 'Unified Computing System', 'Universal Cloud Server', 'Unnecessarily Complex Setup', 'It unifies compute, network, storage, and virtualization.', 'EASY', 'UCS stands for Unified Computing System, Cisco''s integrated infrastructure platform that combines servers, networking, storage access, and virtualization into a single cohesive system.'),
('dc-003', 'DATA_CENTER', 'Which Nexus switch series is designed specifically for spine-leaf data center architectures?', 'Nexus 9000', 'Nexus 7000', 'Nexus 5000', 'It''s the modern 9000 series built for fabrics.', 'MEDIUM', 'The Nexus 9000 series is purpose-built for modern spine-leaf architectures, offering ultra-low latency, high bandwidth, and native ACI support for software-defined data centers.'),
('dc-004', 'DATA_CENTER', 'What is the name of Cisco''s centralized management platform for data center fabrics?', 'Nexus Dashboard', 'APIC', 'The Big Red Button', 'It''s a dashboard for your Nexus environment.', 'MEDIUM', 'Nexus Dashboard is Cisco''s unified operational console for managing ACI, VXLAN, and traditional data center fabrics, providing centralized visibility, automation, and troubleshooting.'),
('dc-005', 'DATA_CENTER', 'Which UCS server form factor is designed for high-density computing?', 'UCS Blade Servers', 'UCS Rack Servers', 'UCS Pizza Box Servers', 'They slide into a chassis for maximum density.', 'MEDIUM', 'UCS Blade Servers (B-Series) are designed for maximum density, sliding into UCS chassis with shared power, cooling, and fabric connectivity for space-efficient data centers.'),
('dc-006', 'DATA_CENTER', 'What network overlay technology does ACI use to create virtual networks?', 'VXLAN', 'OSPF', 'IS-IS', 'It extends VLANs... virtually.', 'MEDIUM', 'ACI uses VXLAN (Virtual Extensible LAN) as its network overlay technology, enabling scalable multi-tenancy and network segmentation across Layer 3 boundaries in the data center.'),
('dc-007', 'DATA_CENTER', 'What is the management controller embedded in UCS servers called?', 'CIMC', 'IMM', 'The Puppet Master', 'It''s Cisco Integrated Management Controller.', 'MEDIUM', 'CIMC (Cisco Integrated Management Controller) is the embedded management interface in UCS servers, providing out-of-band server management, monitoring, and remote console access.'),
('dc-008', 'DATA_CENTER', 'Which Nexus Dashboard service provides AI-powered network insights and recommendations?', 'Nexus Dashboard Insights', 'Nexus Dashboard Analytics', 'Magic 8-Ball as a Service', 'It gives you insights into what''s happening.', 'MEDIUM', 'Nexus Dashboard Insights uses AI and machine learning to provide proactive network visibility, anomaly detection, and actionable recommendations for ACI and VXLAN fabrics.'),
('dc-009', 'DATA_CENTER', 'What is the maximum number of leaf switches supported in a single ACI fabric?', '400', '200', 'As many as you can afford', 'It''s a round number between 200 and 500.', 'MEDIUM', 'A single ACI fabric can scale to 400 leaf switches, supporting massive data center deployments with consistent policy enforcement and seamless multi-site connectivity.'),
('dc-010', 'DATA_CENTER', 'Which UCS component provides unified management across all UCS domains?', 'UCS Manager', 'UCS Central', 'Karen (she wants to speak to the manager)', 'It manages your UCS environment.', 'MEDIUM', 'UCS Manager is the unified management interface for UCS domains, providing service profiles, firmware management, and policy-based automation across compute, network, and storage resources.'),
('dc-011', 'DATA_CENTER', 'What technology allows ACI to extend policies across multiple data centers?', 'Multi-Site', 'Fabric Extend', 'Very Long Ethernet Cable', 'It connects multiple sites together.', 'MEDIUM', 'ACI Multi-Site enables policy consistency and workload mobility across geographically distributed data centers, with centralized orchestration through Multi-Site Orchestrator.'),
('dc-012', 'DATA_CENTER', 'Which Nexus switch includes embedded DPUs for advanced security processing?', 'Nexus 9300 Smart Switch', 'Nexus 9300 Dumb Switch', 'Nexus 9300 Genius Switch', 'It''s smart because it has special processing units.', 'MEDIUM', 'The Nexus 9300 Smart Switch includes embedded NVIDIA BlueField DPUs that provide line-rate security inspection, telemetry processing, and AI workload acceleration without impacting performance.'),
('dc-013', 'DATA_CENTER', 'What does APIC stand for in Cisco ACI?', 'Application Policy Infrastructure Controller', 'Automated Provisioning and Integration Controller', 'A Pretty Impressive Controller', 'It controls the application policy infrastructure.', 'MEDIUM', 'APIC is the centralized controller for ACI fabrics, translating application requirements into network policies and automating fabric configuration across all switches.'),
('dc-014', 'DATA_CENTER', 'Which UCS server generation introduced support for DDR5 memory?', 'UCS X-Series', 'UCS Y-Series', 'UCS Z-Series', 'X marks the spot for the newest generation.', 'MEDIUM', 'UCS X-Series is Cisco''s latest modular compute platform supporting DDR5 memory, PCIe Gen 5, and a future-ready design for AI, machine learning, and high-performance workloads.'),
('dc-015', 'DATA_CENTER', 'What fabric interconnect model is used in UCS blade chassis?', '6400 Series', '5500 Series', '4400 Series', 'It''s in the 6000 range and the latest generation.', 'MEDIUM', 'The UCS 6400 Series Fabric Interconnects provide unified network and storage connectivity for UCS blade and rack servers with 10/25/40/100 Gigabit Ethernet ports.'),
('dc-016', 'DATA_CENTER', 'Which Nexus Dashboard service automates configuration compliance and auditing?', 'Nexus Dashboard Orchestrator', 'Nexus  Fabric Controller', 'Nexus Hall Monitor', 'It orchestrates policies across your environment.', 'MEDIUM', 'Nexus Dashboard Orchestrator provides centralized policy orchestration and compliance management across multiple ACI fabrics and cloud environments with automated auditing.'),
('dc-017', 'DATA_CENTER', 'What is the latency specification for Nexus 9000 series switches?', 'Sub-microsecond', 'Sub-millisecond', 'Sub-phemtosecond', 'It''s measured in millionths of a second.', 'HARD', 'Nexus 9000 switches deliver sub-microsecond latency (less than 1 microsecond), critical for high-frequency trading, AI workloads, and latency-sensitive applications.'),
('dc-018', 'DATA_CENTER', 'Which ACI construct defines the logical grouping of endpoints?', 'Endpoint Group (EPG)', 'Bridge Domain', 'Endpoint Squad Goals', 'It groups endpoints together logically.', 'MEDIUM', 'Endpoint Groups (EPGs) are logical collections of endpoints in ACI that share common policy requirements, enabling simplified policy enforcement regardless of network topology.'),
('dc-019', 'DATA_CENTER', 'What GPU vendor does Cisco partner with for AI-optimized UCS servers?', 'NVIDIA', 'Intel', 'Nintendo', 'The same company that makes GeForce graphics cards.', 'EASY', 'Cisco partners with NVIDIA to integrate GPU accelerators into UCS servers for AI training, inference, and high-performance computing workloads, validated for major AI frameworks.'),
('dc-020', 'DATA_CENTER', 'Which Nexus Dashboard service provides network security policy recommendations?', 'Nexus Dashboard Insights', 'Nexus Dashboard Security', 'Jeeves for Nexus Dashboard', 'The same service that gives AI-powered insights.', 'MEDIUM', 'Nexus Dashboard Insights analyzes traffic patterns and security postures to provide AI-driven recommendations for microsegmentation policies and security improvements in ACI environments.');
